/* From Uiverse.io by david-mohseni - Tags: neumorphism, card */
.__UIV_SCOPE__ .card {
  width: 190px;
  height: 120px;
  background-color: #eee;
  text-align: center;
  border: 10px solid #eee;
  border-radius: 20px;
  box-shadow: inset 5px 5px 10px #bbb, inset -5px -5px 10px #fff;
  transition: 0.5s;
}

.__UIV_SCOPE__ .card:hover {
  height: 254px;
}

.__UIV_SCOPE__ .icon {
  width: 60px;
  height: 60px;
  color: red;
  font-size: 30px;
  background-color: #eee;
  margin: 20px auto;
  padding: 5px;
  border-radius: 50%;
  box-shadow: 8px 8px 10px #ddd, -8px -8px 10px #fff;
}

.__UIV_SCOPE__ .content {
  color: #999;
  background-color: #eee;
  padding: 10px;
  margin: 5px 20px;
  border-radius: 8px;
  box-shadow: 8px 8px 10px #ddd, -8px -8px 10px #fff;
  transform: translateY(-80px) scale(0);
  transition: all 0.5s;
}

.__UIV_SCOPE__ .card:hover .content {
  transform: translateY(0) scale(1)
}

.__UIV_SCOPE__ .content h3 {
  text-shadow: 2px 2px 0px #fff;
}
